#include "../models/closure/AdaptiveContact.cpp"
#include <sofa/component/statecontainer/MechanicalObject.h>
#include <iostream>
using namespace regrip_integrated;
void require(bool p,const char*m){if(!p)throw std::runtime_error(m);}
template<class Parent>struct Acc:Parent{double a[18][18]{};void add(sofa::SignedIndex r,sofa::SignedIndex c,double v)override{a[r][c]+=v;}void add(sofa::SignedIndex r,sofa::SignedIndex c,float v)override{add(r,c,double(v));}};
int main(){try{
 auto state=sofa::core::objectmodel::New<sofa::component::statecontainer::MechanicalObject<Types>>();state->resize(3);auto field=sofa::core::objectmodel::New<ActiveIntervalContact>(state.get());field->segments.setValue({0,1});field->objectIndex.setValue(2);field->samples.setValue(16);field->historySpacing.setValue(.005);
 Inherit::VecCoord x(3);for(auto&p:x)p.getOrientation()=sofa::type::Quat<double>(0,0,0,1);x[0].getCenter()={-2,0,5.09};x[1].getCenter()={2,0,5.09};state->write(sofa::core::vec_id::write_access::restPosition)->setValue(x);field->prepare(x);x[0].getCenter()[0]+=.0001;x[1].getCenter()[0]+=.0001;field->commit(x);auto result=field->compute(x);require(result.elastic>0,"static traction energy nonzero");
 V moment{},force{};for(unsigned i=0;i<3;++i){V f{},m{},p{};for(int j=0;j<3;++j){f[j]=result.a.f[6*i+j];m[j]=result.a.f[6*i+j+3];p[j]=x[i].getCenter()[j];}force=add(force,f);moment=add(moment,add(m,cross(p,f)));}double maxMoment=0;for(double v:moment)maxMoment=std::max(maxMoment,std::abs(v));for(double v:force)require(std::abs(v)<1e-13,"integrated action reaction");require(maxMoment<1e-12,"integrated moment balance");
 const auto oldPrevious=field->previous;auto transformed=x;Q rotation=exp(V{.3,-.2,.4});V translation{1,2,3};auto transform=[&](Types::Coord&p){auto a=EnergyField::pose(p);a.p=add(rotate(rotation,a.p),translation);a.q=multiply(rotation,a.q);for(int j=0;j<3;++j)p.getCenter()[j]=a.p[j];p.getOrientation()={a.q[0],a.q[1],a.q[2],a.q[3]};};for(auto&p:transformed)transform(p);for(auto&p:field->previous)transform(p);auto objective=field->compute(transformed);double covariance=0;
 for(unsigned i=0;i<3;++i)for(unsigned offset:{0u,3u}){auto expected=rotate(rotation,V{result.a.f[6*i+offset],result.a.f[6*i+offset+1],result.a.f[6*i+offset+2]});for(int j=0;j<3;++j)covariance=std::max(covariance,std::abs(expected[j]-objective.a.f[6*i+offset+j]));}require(covariance<1e-12&&std::abs(objective.a.energy-result.a.energy)<1e-14,"material history objectivity");field->previous=oldPrevious;
 state->write(sofa::core::vec_id::write_access::position)->setValue(x);auto assembled=field->compute(x).a;Inherit::DataVecDeriv dx,df;Inherit::VecDeriv values(3);for(auto&v:values)for(int j=0;j<6;++j)v[j]=.001*(j+1);dx.setValue(values);df.setValue(Inherit::VecDeriv(3));sofa::core::MechanicalParams mp;mp.setKFactor(2.5);field->addDForce(&mp,df,dx);double expected[18]{};for(auto&t:assembled.J)expected[t.r]+=2.5*t.v*values[t.c/6][t.c%6];for(int i=0;i<18;++i)require(std::abs(expected[i]-df.getValue()[i/6][i%6])<1e-13,"adaptive addDForce kFactor");
 Acc<sofa::core::behavior::StiffnessMatrixAccumulator>acc;sofa::core::behavior::StiffnessMatrix matrix;matrix.setMatrixAccumulator(&acc,state.get());field->buildStiffnessMatrix(&matrix);double J[18][18]{};for(auto&t:assembled.J)J[t.r][t.c]+=t.v;for(int i=0;i<18;++i)for(int j=0;j<18;++j)require(std::abs(J[i][j]-acc.a[i][j])<1e-14,"adaptive actual stiffness accumulator");
 auto separate=x;separate[0].getCenter()[2]+=1;separate[1].getCenter()[2]+=1;field->commit(separate);require(field->compute(separate).a.contacts==0&&field->released>0,"release/reset/separate energy accounting");field->commit(x);require(field->compute(x).elastic<1e-20,"reentry no inherited traction");
 field->segments.setValue({0,99});bool invalid=false;try{field->compute(x);}catch(const std::invalid_argument&){invalid=true;}require(invalid,"invalid runtime indices safe");
 std::cout<<std::setprecision(17)<<"PASS adaptive objectivity/action-reaction/moment/addDForce/buildStiffness/kFactor/release/reentry/invalid; moment="<<maxMoment<<" covariance="<<covariance<<'\n';
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
